edits.after:
root = kernfs_root(kn);
down_read(&root->kernfs_rwsem);

knparent = find_next_ancestor(kn, NULL);
if (WARN_ON(!knparent)) {
	up_read(&root->kernfs_rwsem);
	dput(dentry);
	return ERR_PTR(-EINVAL);
}
up_read(&root->kernfs_rwsem);

do {
	struct dentry *dtmp;
	struct kernfs_node *kntmp;
	const char *name;
	char *name_copy;

	if (kn == knparent)
		return dentry;

	down_read(&root->kernfs_rwsem);
	kntmp = find_next_ancestor(kn, knparent);
	if (WARN_ON(!kntmp)) {
		up_read(&root->kernfs_rwsem);
		dput(dentry);
		return ERR_PTR(-EINVAL);
	}
	name = kernfs_rcu_name(kntmp);
	name_copy = kstrdup(name, GFP_KERNEL);
	if (!name_copy) {
		up_read(&root->kernfs_rwsem);
		dput(dentry);
		return ERR_PTR(-ENOMEM);
	}
	up_read(&root->kernfs_rwsem);

	dtmp = lookup_positive_unlocked(name_copy, dentry, strlen(name_copy));
	kfree(name_copy);
	dput(dentry);
	if (IS_ERR(dtmp))
		return dtmp;
	knparent = kntmp;
	dentry = dtmp;
} while (true);

